const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解：设未知数为 x' },
      { kind: 'text', payload: '由题意列方程' },
      { kind: 'text', payload: '移项得' },
      { kind: 'text', payload: '（原图中学生手写作答已擦除）' }
    ];
  },
  render: function (input, metrics) {
    var m = metrics || [];
    var lines = ['解：设未知数为 x', '由题意列方程', '移项得'];
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x = 68;
    var y = 80;
    var gap = 24;
    var lastY = y;
    var children = [];
    var i;
    for (i = 0; i < lines.length; i++) {
      var info = m[i] || {};
      var h = info.height || 26;
      children.push({
        type: 'label',
        x: x,
        y: y,
        text: lines[i],
        fontSize: 20,
        fill: '#1f2a37'
      });
      lastY = y;
      y = y + h + gap;
    }
    var noteY = Math.min(H - 22, lastY + 56);
    children.push({
      type: 'label',
      x: x,
      y: noteY,
      text: '（原图中学生手写作答已擦除）',
      fontSize: 13,
      fill: '#8a93a0'
    });
    var frame = visualSdk.polyline([
      [16, 16], [W - 16, 16], [W - 16, H - 16], [16, H - 16], [16, 16]
    ]);
    var accent = visualSdk.polyline([
      [44, 52], [44, lastY + 10]
    ]);
    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'frame', stroke: '#c7d0da', strokeWidth: 1 },
        { type: 'path', pathId: 'accent', stroke: '#4a90d9', strokeWidth: 3 }
      ]
    };
    for (i = 0; i < children.length; i++) {
      root.children.push(children[i]);
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-transcription-clean',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'frame', commands: frame },
        { id: 'accent', commands: accent }
      ],
      root: root
    };
  }
};
